def nest(d):
    if d == 0:
        return {'op': 'contains', 'path': ['a']}
    return {'op': 'not', 'arg': {'op': 'and', 'args': [nest(d - 1), {'op': 'true'}]}}
for d in (19, 20, 21, 22):
    req = {'services': ['a'], 'rules': [{'action': 'allow', 'when': nest(d)}], 'queries': [['a']]}
